WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_judgement_analogy_logical_condition'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '条件关系', 'kp-xingce-judgement-analogy-logical-condition', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "条件关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "A 是 B 发生的条件。区分充分和必要。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心战法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“水 : 鱼” -> 没有水鱼必死（必要条件）。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“下雨 : 地湿” -> 下雨地一定湿（充分条件）。"}]}]}$$ AS jsonb), NULL, '条件关系的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "条件关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_analogy_logical_condition", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
